ALTER TABLE public.products ADD COLUMN catalogue_visible boolean NOT NULL DEFAULT false, ADD COLUMN specifications text NOT NULL DEFAULT '', ADD COLUMN documentation_url text NOT NULL DEFAULT '', ADD COLUMN intended_use text NOT NULL DEFAULT '', ADD COLUMN featured boolean NOT NULL DEFAULT false;
ALTER TABLE public.products ALTER COLUMN catalogue_visible SET DEFAULT true;
ALTER POLICY "public read active" ON public.products USING ((active AND catalogue_visible) OR public.has_role(auth.uid(), 'admin'));
ALTER TABLE public.site_settings ADD COLUMN business_description text NOT NULL DEFAULT '', ADD COLUMN home_intro text NOT NULL DEFAULT '', ADD COLUMN services_text text NOT NULL DEFAULT '', ADD COLUMN quality_text text NOT NULL DEFAULT '', ADD COLUMN public_contact_verified boolean NOT NULL DEFAULT false, ADD COLUMN canonical_origin text NOT NULL DEFAULT '', ADD COLUMN home_seo_title text NOT NULL DEFAULT '', ADD COLUMN home_seo_description text NOT NULL DEFAULT '', ADD COLUMN shop_seo_title text NOT NULL DEFAULT '', ADD COLUMN shop_seo_description text NOT NULL DEFAULT '', ADD COLUMN contact_seo_title text NOT NULL DEFAULT '', ADD COLUMN contact_seo_description text NOT NULL DEFAULT '';
COMMENT ON COLUMN public.products.catalogue_visible IS 'Administrator approval for peptide catalogue; legacy pharmacy products remain stored but excluded.';
DROP POLICY IF EXISTS "anyone can order" ON public.orders;
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), email text NOT NULL CHECK(length(email) BETWEEN 3 AND 254), subject text NOT NULL CHECK(length(subject) BETWEEN 1 AND 200), message text NOT NULL CHECK(length(message) BETWEEN 1 AND 5000), created_at timestamptz NOT NULL DEFAULT now(), is_read boolean NOT NULL DEFAULT false, archived boolean NOT NULL DEFAULT false);
GRANT SELECT,UPDATE,DELETE ON public.enquiries TO authenticated; GRANT ALL ON public.enquiries TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_enquiries ON public.enquiries FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.chat_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL, name text NOT NULL, email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), archived boolean NOT NULL DEFAULT false, admin_read_at timestamptz NOT NULL DEFAULT now(), last_visitor_at timestamptz);
GRANT SELECT,UPDATE,DELETE ON public.chat_conversations TO authenticated; GRANT ALL ON public.chat_conversations TO service_role;
ALTER TABLE public.chat_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_conversations ON public.chat_conversations FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.chat_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.chat_conversations(id) ON DELETE CASCADE, sender text NOT NULL CHECK(sender IN ('visitor','admin')), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.chat_messages TO authenticated; GRANT ALL ON public.chat_messages TO service_role;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_messages ON public.chat_messages FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_send_messages ON public.chat_messages FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND sender='admin');
CREATE POLICY admin_delete_messages ON public.chat_messages FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX chat_messages_conversation_time ON public.chat_messages(conversation_id,created_at);
CREATE TABLE public.messaging_rate_limits (key text PRIMARY KEY, started_at timestamptz NOT NULL DEFAULT now(), hits integer NOT NULL DEFAULT 1);
GRANT ALL ON public.messaging_rate_limits TO service_role;
ALTER TABLE public.messaging_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.consume_messaging_limit(rate_key text, max_hits integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.messaging_rate_limits(key) VALUES(rate_key) ON CONFLICT(key) DO UPDATE SET hits=CASE WHEN messaging_rate_limits.started_at < now()-interval '10 minutes' THEN 1 ELSE messaging_rate_limits.hits+1 END, started_at=CASE WHEN messaging_rate_limits.started_at < now()-interval '10 minutes' THEN now() ELSE messaging_rate_limits.started_at END RETURNING hits INTO n; RETURN n<=max_hits; END; $$;
REVOKE ALL ON FUNCTION public.consume_messaging_limit(text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_messaging_limit(text,integer) TO service_role;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND tablename='chat_messages') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.chat_messages; END IF; IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND tablename='chat_conversations') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.chat_conversations; END IF; END $$;